import com.badlogic.gdx.utils.GdxRuntimeException;
import javax.annotation.Nullable;

public class ETC1TextureData implements TextureData {
  @Nullable FileHandle file;
  @Nullable ETC1Data data;
  boolean useMipMaps;
  int width = 0;
  int height = 0;
  boolean isPrepared = false;

  public ETC1TextureData(FileHandle file) {
    this(file, false);
  }

  @SuppressWarnings("NullAway.Init")
  public ETC1TextureData(FileHandle file, boolean useMipMaps) {
    this.file = file;
    this.useMipMaps = useMipMaps;
  }

  public ETC1TextureData(ETC1Data encodedImage, boolean useMipMaps) {
    this.data = encodedImage;
    this.useMipMaps = useMipMaps;
  }

  @Override
  public TextureDataType getType() {
    return TextureDataType.Custom;
  }

  @Override
  public boolean isPrepared() {
    return isPrepared;
  }

  @Override
  public void prepare() {
    if (isPrepared) throw new GdxRuntimeException("Already prepared");
    if (file == null && data == null)
      throw new GdxRuntimeException("Can only load once from ETC1Data");
    if (file != null) {
      data = new ETC1Data(file);
    }
    if (data == null) throw new GdxRuntimeException("ETC1Data not prepared");
    width = data.width;
    height = data.height;
    isPrepared = true;
  }

  @Override
  public void consumeCustomData(int target) {
    if (!isPrepared)
      throw new GdxRuntimeException("Call prepare() before calling consumeCompressedData()");
    if (data == null) throw new GdxRuntimeException("ETC1Data not prepared");

    if (!Gdx.graphics.supportsExtension("GL_OES_compressed_ETC1_RGB8_texture")) {
      Pixmap pixmap = ETC1.decodeImage(data, Format.RGB565);
      Gdx.gl.glTexImage2D(
          target,
          0,
          pixmap.getGLInternalFormat(),
          pixmap.getWidth(),
          pixmap.getHeight(),
          0,
          pixmap.getGLFormat(),
          pixmap.getGLType(),
          pixmap.getPixels());
      if (useMipMaps)
        MipMapGenerator.generateMipMap(target, pixmap, pixmap.getWidth(), pixmap.getHeight());
      pixmap.dispose();
      useMipMaps = false;
    } else {
      Gdx.gl.glCompressedTexImage2D(
          target,
          0,
          ETC1.ETC1_RGB8_OES,
          width,
          height,
          0,
          data.compressedData.capacity() - data.dataOffset,
          data.compressedData);
